import {esc,button,eyebrow,kindLabels} from './components.js';
import {uiContext} from './context.js';
import {MAX_ROUND} from '../model/practice.js';
export function practiceSettings(s){
  const {t}=uiContext(s),counts=s.inventory;
  return `<form class="practice-settings" data-form="settings"><div><label for="practice-mode">${t('whatPractice')}</label><select name="mode" id="practice-mode">${['path','word','sentence','reply','spelling'].map(id=>`<option value="${id}" ${s.profile.mode===id?'selected':''}>${t(id)}</option>`).join('')}</select></div><div><label for="practice-length">${t('length')}</label><select name="length" id="practice-length">${[...Array.from({length:MAX_ROUND},(_,index)=>index+1),'all'].map(id=>`<option value="${id}" ${s.profile.length===id?'selected':''}>${id==='all'?t('all'):t(id===1?'exercise':'exercises',{count:id})}</option>`).join('')}</select></div><p class="fine">${t('inventory',{words:counts.word.length,sentences:counts.sentence.length,replies:counts.reply.length})}<br>${t('spellingCount',{count:counts.spelling.length})}</p></form>`;
}
export function practiceView(s,topic){
  const {t,target,targetLanguage}=uiContext(s);
  if(s.page==='lesson'){
    const card=s.cards[s.index],translation=card.kind==='word'?card.meaning.answers[0]:['reply','spelling'].includes(card.kind)?card.german:card.prompt;
    const prompt=card.kind==='word'?'wordQuestion':card.kind==='spelling'?'spellingQuestion':'sentenceQuestion';
    return `<section class="narrow lesson ${card.kind==='word'?'':'sentence-lesson'}">${eyebrow((card.kind==='spelling'?t('kindSpelling'):topic.name)+' / '+t('questionCount',{index:s.index+1,total:s.cards.length}))}<progress class="track" value="${s.index}" max="${s.cards.length}" aria-label="${esc(t('questionCount',{index:s.index+1,total:s.cards.length}))}"></progress><span class="exercise-type">${t(kindLabels[card.kind])}</span>
    ${card.kind==='reply'?`<div class="conversation"><span>${t('heard')}</span><p lang="${targetLanguage}">${esc(card.heard)}</p><details><summary>${t('showMeaning')}</summary><p>${esc(card.heardGerman)}</p></details></div><p class="prompt">${t('task')}</p><h1 class="question situation">${esc(card.prompt)}</h1>`:`<p class="prompt">${t(prompt,{target})}</p><h1 class="question">${esc(card.prompt)}</h1>`}
    <p class="fine">${card.kind==='reply'?t('replyHint'):card.kind==='spelling'?esc(t('intended',{meaning:card.german})):t('think')}</p><form data-form="answer"><label for="answer">${t('yourAnswer',{target})}</label><textarea id="answer" name="answer" lang="${targetLanguage}" rows="${card.kind==='word'?1:3}" autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" maxlength="1000" ${s.checked&&!s.retrying?'disabled':''}>${esc(s.answer)}</textarea><div aria-live="polite">${s.revealed?`<div class="feedback ${s.correct?'success':''}"><strong>${s.correct?'✓ '+t(s.formHint?'acceptedForm':s.spelling?'acceptedSpelling':'correct'):t(s.spelling?'almost':'expected')}</strong><p class="expected-answer" lang="${targetLanguage}">${esc(s.formHint?s.modelAnswer:card.answers[0])}</p><p>${esc(translation)}</p>${!s.correct&&!s.spelling?`<small>${t('limited')}</small>`:''}</div>`:''}</div>${s.checked?`${s.retrying?button(t('recheckAnswer'),'submit','type="submit"'):!s.correct?button(t('editAnswer'),'retry-answer','type="button"'):''}${button(t(s.index+1===s.cards.length?'finish':'next'),'next','type="button"')}`:button(t('checkAnswer'),'submit','type="submit"')}${!s.checked?`<button class="text-button" data-action="dont-know" type="button">${t('dontKnow')}</button>`:''}</form><button class="text-button" data-action="home">${t('leave')}</button></section>`;
  }
  if(s.page==='done')return `<section class="narrow complete"><span class="complete-symbol" aria-hidden="true">✳</span>${eyebrow(t('done'))}<h1>${t('wordToTalk')}</h1><p class="lead">${t('score',{correct:s.sessionCorrect,total:s.cards.length})}</p><div class="recap">${s.cards.map(c=>`<div><strong lang="${targetLanguage}">${esc(c.answers[0])}<small>${t(kindLabels[c.kind])}</small></strong><span>${esc(c.kind==='word'?c.meaning.answers[0]:['reply','spelling'].includes(c.kind)?c.german:c.prompt)}</span></div>`).join('')}</div>${button(t('again'),'start')}${button(t('home'),'home')}</section>`;
  return '';
}
